set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000001401',true);
do $$ declare c uuid:='00000000-0000-0000-0000-000000001420';t uuid;m uuid;a uuid;other uuid;denial uuid;w jsonb;begin
 t:=public.save_course_topic(c,'First topic','Description',1);
 other:=public.save_course_topic('00000000-0000-0000-0000-000000001421','Other topic','',1);
 m:=public.save_course_text(c,'lecture','Lecture','Body');
 a:=public.create_assignment(c,'Task','Description',null,100,false);
 perform public.link_course_topic(c,m,'material',t);perform public.link_course_topic(c,a,'assignment',t);
 begin perform public.link_course_topic(c,m,'material',other);raise exception 'Cross course allowed';exception when raise_exception then if sqlerrm<>'Topic belongs to another course' then raise;end if;end;
 perform public.save_course_topic(c,'Updated','',2,t,1);
 begin perform public.save_course_topic(c,'Stale','',1,t,1);raise exception 'Stale overwrite allowed';exception when raise_exception then if sqlerrm<>'Topic changed. Refresh before saving' then raise;end if;end;
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000001402',true);
 w:=public.course_workspace(c);if jsonb_array_length(w->'topics')<>1 or jsonb_array_length(w->'links')<>2 or (w->>'canManage')::boolean then raise exception 'Student workspace invalid';end if;
 perform public.complete_course_topic(t,true);perform public.complete_course_topic(t,true);
 if jsonb_array_length(public.course_workspace(c)->'completed')<>1 then raise exception 'Progress lost';end if;
 begin perform public.save_course_topic(c,'Student topic','',1);raise exception 'Student can manage';exception when raise_exception then if sqlerrm<>'Access denied' then raise;end if;end;
 begin perform public.link_course_topic(c,m,'material',null);raise exception 'Student can link';exception when raise_exception then if sqlerrm<>'Access denied' then raise;end if;end;
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000001403',true);
 if jsonb_array_length(public.course_workspace(c)->'completed')<>0 then raise exception 'Private progress leaked';end if;
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000001404',true);
 begin perform public.course_workspace(c);raise exception 'Foreign account read';exception when raise_exception then if sqlerrm<>'Course access denied' then raise;end if;end;
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000001401',true);
 denial:=public.deny_section('lectures','00000000-0000-0000-0000-000000001402',null);
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000001402',true);
 if jsonb_array_length(public.course_workspace(c)->'links')<>1 then raise exception 'Denied lecture link leaked';end if;
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000001401',true);perform public.remove_denial(denial);
 perform public.delete_course_topic(t,2);
 if not public.read_course_material(m) or not public.can_read_assignment(a) or jsonb_array_length(public.course_workspace(c)->'topics')<>0 or jsonb_array_length(public.course_workspace(c)->'links')<>0 then raise exception 'Topic deletion damaged content';end if;
end $$;
